def is_valid_sudoku_row(row):
    if len(row) != 9:
        return False
    seen = set()
    for x in row:
        if x == 0:
            continue
        if not (1 <= x <= 9):
            return False
        if x in seen:
            return False
        seen.add(x)
    return True

def oxford_join_quoted(items):
    quoted = [f'"{i}"' for i in items]
    if not quoted:
        return ""
    if len(quoted) == 1:
        return quoted[0]
    if len(quoted) == 2:
        return f"{quoted[0]} and {quoted[1]}"
    return ", ".join(quoted[:-1]) + f", and {quoted[-1]}"

def condense_whitespace(s):
    result = []
    prev_space = False
    for c in s:
        if c.isspace():
            if not prev_space:
                result.append(' ')
            prev_space = True
        else:
            result.append(c)
            prev_space = False
    return "".join(result).strip()

