def is_last_occurrence_of_weekday(year, month, day, weekday_num):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def wd(y, m, d):
        if m < 3:
            m += 12
            y -= 1
        K = y % 100
        J = y // 100
        h = (d + (13 * (m + 1)) // 5 + K + K // 4 + J // 4 + 5 * J) % 7
        return (h + 5) % 7
    dim = [31, 29 if is_leap(year) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1]
    if wd(year, month, day) != weekday_num:
        return False
    return day + 7 > dim

def round_robin_merge_three_rankings(list1, list2, list3):
    lists = [list1, list2, list3]
    idxs = [0, 0, 0]
    result = []
    seen = set()
    while any(idxs[k] < len(lists[k]) for k in range(3)):
        for k in range(3):
            if idxs[k] < len(lists[k]):
                v = lists[k][idxs[k]]
                if v not in seen:
                    result.append(v)
                    seen.add(v)
                idxs[k] += 1
    return result

def capitalize_first_word_each_line(text):
    lines = text.split("\n")
    out = []
    for line in lines:
        if line == "":
            out.append(line)
            continue
        lowered = line.lower()
        fixed = lowered
        for i, ch in enumerate(lowered):
            if ch.isalpha():
                fixed = lowered[:i] + ch.upper() + lowered[i + 1:]
                break
        out.append(fixed)
    return "\n".join(out)

def most_frequent_element(lst):
    counts = {}
    for x in lst:
        counts[x] = counts.get(x, 0) + 1
    best = lst[0]
    best_count = counts[lst[0]]
    for x in lst:
        if counts[x] > best_count:
            best = x
            best_count = counts[x]
    return best

