def is_valid_parity_bit_string(s):
    if len(s) < 2 or any(c not in '01' for c in s):
        return False
    return s.count('1') % 2 == 0

def merge_rankings_by_position_sum(list1, list2):
    pos1 = {v: i for i, v in enumerate(list1)}
    pos2 = {v: i for i, v in enumerate(list2)}
    items = set(list1) | set(list2)
    def score(x):
        if x in pos1 and x in pos2:
            return pos1[x] + pos2[x]
        if x in pos1:
            return 2 * pos1[x]
        return 2 * pos2[x]
    return sorted(items, key=lambda x: (score(x), x))

def is_palindrome(s):
    filtered = [c.lower() for c in s if c.isalnum()]
    return filtered == filtered[::-1]

def is_valid_hex_string_even_length(s):
    if not s or len(s) % 2 != 0:
        return False
    hexdigits = set('0123456789abcdefABCDEF')
    return all(c in hexdigits for c in s)

def min_left_rotations_to_sort(lst):
    n = len(lst)
    if n <= 1:
        return 0
    target = sorted(lst)
    for k in range(n):
        if lst[k:] + lst[:k] == target:
            return k
    return -1

