def is_valid_subnet_mask(s):
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for p in parts:
        if not p.isdigit() or int(p) > 255:
            return False
    bits = ''.join(format(int(p), '08b') for p in parts)
    ones = bits.find('0')
    if ones == -1:
        return True
    return '1' not in bits[ones:]
